    find: "  const rewardCents = Math.min(rewardCentsRaw, subtotalCents);",
    replace:
      "  const rewardCents = Math.min(rewardCentsRaw, Math.max(subtotalCents - Math.min(promoCentsRaw, subtotalCents), 0));",
